import json
prog='''from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for r in grid for x in r).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    dq = deque()
    for i in range(h):
        for j in (0, w - 1):
            if grid[i][j] == bg and not seen[i][j]:
                seen[i][j] = True; dq.append((i, j))
    for j in range(w):
        for i in (0, h - 1):
            if grid[i][j] == bg and not seen[i][j]:
                seen[i][j] = True; dq.append((i, j))
    while dq:
        i, j = dq.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            a, b = i + di, j + dj
            if 0 <= a < h and 0 <= b < w and not seen[a][b] and grid[a][b] == bg:
                seen[a][b] = True; dq.append((a, b))
    return [[4 if (grid[i][j] == bg and not seen[i][j]) else grid[i][j] for j in range(w)] for i in range(h)]
'''
